#!/usr/bin/env bash
# Gate `five-root-documents` for [R:five-files-no-more], generated by relearn from the rule file.
# Edit the rule, never this script: `relearn verify` reports a hand edit.
# Engine: root-documents. Records: path, tab-separated.
#   bash five-root-documents.sh <repository root>   0 clean, 1 finding, 2 could not check
#   bash five-root-documents.sh --judge < records   0 clean, 1 hit (the fixture runner)
# A `warn` gate prints its finding and exits 0.
set -uo pipefail
export LC_ALL=C

name='five-root-documents'
tag='R:five-files-no-more'
message='A standing document at the repository root beyond the five (README, CLAUDE, ARCHITECTURE, FEATURES, TODO). Fold its content into one of the five, or into a domain rule if it generalises, unless it is a convention a host reads by name (a changelog, a contribution guide). AGENTS.md is exempt because relearn generates it.'
export RL_FILES='((^|/)[^/]*\.md$)'
export RL_EXCLUDE='((^|/)README\.md$)|((^|/)CLAUDE\.md$)|((^|/)ARCHITECTURE\.md$)|((^|/)FEATURES\.md$)|((^|/)TODO\.md$)|((^|/)AGENTS\.md$)'

# Judge: 1 field(s) per record on stdin. 0 clean, 1 hit, 3 unreadable.
judge() {
  awk '
BEGIN {
  FS = "\t"
  files = ENVIRON["RL_FILES"]
  excl = ENVIRON["RL_EXCLUDE"]
  hits = 0
  bad = 0
}
$0 == "" { next }
NF != 1 { bad = 1; next }
index($1, "/") { next }
$1 !~ files { next }
excl != "" && $1 ~ excl { next }
{ print $1; hits++ }
END { if (bad) exit 3; exit (hits > 0) }
'
}

# Collect: every tracked path.
collect() {
  git -C "$1" ls-files -z | tr '\0' '\n'
}

if [ "${1:-}" = "--judge" ]; then
  judge
  exit $?
fi

disarmed() {
  printf '[%s] %s: DISARMED (exit 2, not a pass): %s\n' "$tag" "$name" "$1" >&2
  exit 2
}
root="${1:-.}"
command -v git >/dev/null 2>&1 || disarmed "git is not on PATH"
git -C "$root" rev-parse --is-inside-work-tree >/dev/null 2>&1 \
  || disarmed "$root is not a git checkout"
work="$(mktemp -d)" || disarmed "no scratch directory"
trap 'rm -rf "$work"' EXIT
collect "$root" > "$work/records" || disarmed "the collect stage failed"
judge < "$work/records" > "$work/findings"
case $? in
  0) exit 0 ;;
  1) ;;
  *) disarmed "the judge could not read a record" ;;
esac
count="$(wc -l < "$work/findings" | tr -d ' ')"
printf '[%s] %s: WARNING. %s\n' "$tag" "$name" "$message"
printf '%s finding(s) in %s:\n' "$count" "$root"
sed 's/^/  /' "$work/findings"
exit 0

